var i=[{id:"wythoff",title:"Wythoff",kicker:"Strat\xE9gie math\xE9matique",description:"Vide les deux piles en trouvant les positions gagnantes.",objective:"Retirer le dernier jeton pour gagner.",rules:["Le plateau commence avec deux piles de 5 \xE0 15 jetons.","\xC0 ton tour, clique sur un jeton : ce jeton et tous ceux plac\xE9s apr\xE8s lui sont retir\xE9s de cette pile.","Tu peux aussi retirer le m\xEAme nombre de jetons dans les deux piles gr\xE2ce aux boutons sous le plateau.","Tu dois retirer au moins un jeton. Le joueur qui retire le dernier jeton gagne."],tag:"Calcul"},{id:"nim-limite",title:"Nim \u2014 retrait limit\xE9",kicker:"Strat\xE9gie math\xE9matique",description:"Vide les piles en respectant le maximum de jetons autoris\xE9 par tour.",objective:"Retirer le dernier jeton pour gagner.",rules:["La partie commence avec 3 \xE0 5 piles contenant chacune de 4 \xE0 12 jetons.","Le maximum de jetons \xE0 retirer par tour est tir\xE9 au sort : 3, 4 ou 5. Il reste le m\xEAme pendant toute la partie.","\xC0 ton tour, retire au moins un jeton sans d\xE9passer le maximum indiqu\xE9, dans une seule pile. Tu ne peux pas prendre dans plusieurs piles \xE0 la fois.","Clique sur un jeton pour le retirer avec tous ceux plac\xE9s apr\xE8s lui, ou utilise les boutons de retrait de sa pile.","Le joueur qui retire le dernier jeton gagne."],tag:"Jetons"},{id:"nim-emission",title:"Nim \u2014 \xE9mission",kicker:"Jeu t\xE9l\xE9vis\xE9",description:"Retire les drapeaux avec la r\xE8gle surprise de la manche.",objective:"Suivre la r\xE8gle r\xE9v\xE9l\xE9e : prendre le dernier drapeau, ou \xEAtre celui qui ne le prend pas.",rules:["La partie commence avec une seule pile de 18 \xE0 25 drapeaux, tir\xE9e au sort.","Le maximum autoris\xE9 par tour est tir\xE9 au sort : 3, 4 ou 5 drapeaux. Tu peux toujours en retirer au moins 1.","La r\xE8gle de la manche est r\xE9v\xE9l\xE9e au d\xE9but : prendre le dernier drapeau fait gagner, ou prendre le dernier drapeau fait perdre.","Clique sur l\u2019un des derniers drapeaux autoris\xE9s ou utilise les boutons de retrait sous la pile."],tag:"Drapeaux"},{id:"isola",title:"Isolation",kicker:"D\xE9placement et blocage",description:"D\xE9place ton pion puis coupe une case pour enfermer l\u2019adversaire.",objective:"\xCAtre le dernier joueur capable de d\xE9placer son pion.",rules:["Chaque joueur poss\xE8de un pion sur une grille de 5 \xD7 5.","D\xE9place ton pion d\u2019une case dans l\u2019une des huit directions, diagonales comprises.","Apr\xE8s le d\xE9placement, retire d\xE9finitivement une case libre, n\u2019importe o\xF9 sur le plateau.","Une case retir\xE9e ou occup\xE9e ne peut plus \xEAtre utilis\xE9e. Un joueur sans d\xE9placement l\xE9gal perd."],tag:"Blocage"},{id:"domineering",title:"Domineering",kicker:"Placement strat\xE9gique",description:"Occupe l\u2019espace avec des dominos horizontaux ou verticaux.",objective:"Jouer le dernier domino l\xE9gal.",rules:["La partie se joue sur une grille de 5 \xD7 5 cases.","Le joueur 1 pose uniquement des dominos horizontaux; le joueur 2 pose uniquement des dominos verticaux.","Clique une premi\xE8re case puis la case voisine pour placer un domino. Les dominos ne peuvent pas se chevaucher.","Le joueur qui ne peut plus placer son domino perd."],tag:"Placement"},{id:"sim",title:"Sim",kicker:"Pi\xE8ges g\xE9om\xE9triques",description:"Relie les points sans \xEAtre le premier \xE0 fermer un triangle.",objective:"\xC9viter de former un triangle enti\xE8rement de ta couleur.",rules:["Six points sont dispos\xE9s en cercle et chaque paire de points peut \xEAtre reli\xE9e une seule fois.","\xC0 ton tour, choisis une ar\xEAte libre. Les lignes peuvent se croiser.","Les intersections ne cr\xE9ent pas de nouveaux points.","Si ton coup ferme un triangle dont les trois ar\xEAtes sont de ta couleur, tu perds imm\xE9diatement."],tag:"Logique"},{id:"hex",title:"Hex",kicker:"Connexion de chemins",description:"Construis une cha\xEEne continue avant que l\u2019autre couleur ne traverse le plateau.",objective:"Relier ses deux c\xF4t\xE9s oppos\xE9s avant l\u2019adversaire.",rules:["Le plateau est une grille de 5 \xD7 5 cases hexagonales.","Rouge doit relier le haut et le bas; bleu doit relier la gauche et la droite.","\xC0 ton tour, pose un jeton sur une case vide. Les jetons restent en place.","Seules les cases qui partagent un c\xF4t\xE9 sont connect\xE9es. Le premier chemin continu gagne."],tag:"Chemin"}],r=i.map(e=>`/${e.id}`);export{i as a};
